const menu=document.getElementById('menu'),nav=document.getElementById('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.hidden=!open});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.hidden=true;menu.setAttribute('aria-expanded','false')}));fetch(new URL('affiliate-links.json', document.currentScript.src)).then(r=>r.json()).then(links=>{document.querySelectorAll('[data-affiliate]').forEach(a=>{const entry=links[a.dataset.affiliate];if(entry?.url&&/^https:\/\//.test(entry.url))a.href=entry.url})});const modal=document.getElementById('modal');const copy={policy:['プライバシーポリシー','当サイトでは、入力フォームによる個人情報の収集は行っていません。おすすめ記事の表示には、このブラウザ内の閲覧記事・選択テーマを使用します。この履歴はサーバーに送信せず、各おすすめ記事欄からリセットできます。掲載先へ移動した後の情報の取り扱いは各サービスのプライバシーポリシーをご確認ください。\n広告リンクには、成果の計測のためにCookieなどが使用される場合があります。'],editorial:['掲載情報について','当サイトは転職エージェントを紹介する比較メディアです。プロモーションを含みます。掲載順は当サイトの紹介順であり、利用者評価に基づくランキングではありません。\n参照元：MyVision公式サイト（my-vision.co.jp/feature）、AXIS Agent公式サイト（axc.ne.jp）、ASSIGN AGENT公式サイト（assign-inc.com/agent）。情報確認日：2026年10月10日。\n支援内容・対象者・求人情報は変更される場合があります。ご利用前に公式情報をご確認ください。']};document.querySelectorAll('[data-modal]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('modal-title').textContent=copy[b.dataset.modal][0];document.getElementById('modal-body').textContent=copy[b.dataset.modal][1];modal.showModal()}));document.getElementById('close-modal').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
